typedef struct {
    int x;
    int y;
} Ponto;

/* escreva AQUI a caixa moverVia, com as tres janelas:

       void moverVia(Ponto *p, int dx, int dy)

   A primeira janela recebe o ENDERECO de uma ficha. Dentro da caixa,
   some dx no campo x e dy no campo y da ficha apontada, pela flecha
