#include <stdio.h>

/* teste do desafio o-movedor-de-verdade — counter_protocol (03-tdd 3.9.3).
   Fase VALOR: nao ha captura de stdout aqui. O molde da ficha e declarado no
   proprio teste, com os MESMOS campos do molde do aluno, e cada cenario passa
   o ENDERECO da sua ficha (&p) para a caixa. O que o teste confere e o estado
   do ORIGINAL depois da chamada: uma caixa que mexesse na copia deixaria os
   campos como estavam. */

typedef struct {
    int x;
    int y;
} Ponto;

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void moverVia(Ponto *p, int dx, int dy);

SM_TEST(a_ficha_do_original_anda) {
    Ponto p = {3, 4};
    moverVia(&p, 2, 5);
    checa_int("o x do original", p.x, 5,
              "moverVia soma o dx no campo x da ficha apontada: 3 + 2 da 5");
    checa_int("o y do original", p.y, 9,
              "moverVia soma o dy no campo y da MESMA ficha: 4 + 5 da 9");
}

SM_TEST(dois_passos_seguidos) {
    Ponto p = {0, 0};
    moverVia(&p, 1, 1);
    moverVia(&p, 3, 4);
    checa_int("o x depois de dois passos", p.x, 4,
              "cada chamada soma na ficha que a anterior ja mudou: 0 + 1 + 3");
    checa_int("o y depois de dois passos", p.y, 5,
              "0 + 1 + 4 da 5: o original guarda o que a caixa escreveu");
}

SM_TEST(cada_ficha_anda_a_sua) {
    Ponto a = {1, 1};
    Ponto b = {10, 10};
    moverVia(&a, 2, 0);
    moverVia(&b, 0, 5);
    checa_int("o x da ficha a", a.x, 3,
              "o endereco passado escolhe a ficha: a ficha a andou 2 em x");
    checa_int("o y da ficha a", a.y, 1,
              "com dy igual a 0 o campo y da ficha a fica como estava");
    checa_int("o y da ficha b", b.y, 15,
              "a ficha b andou 5 em y na sua propria chamada: 10 + 5 da 15");
}

solutionCode:
typedef struct {
    int x;
    int y;
} Ponto;

void moverVia(Ponto *p, int dx, int dy) {
    p->x += dx;
    p->y += dy;
}
